"""121Q6C Step 003: minimal READ-ONLY legacy asset importer.

Scope: ONLY assets classified IMPORTABLE_NOW in asset-bridge-audit-35.json
(core framework definitions: meta_function + psi0_definition).
Produces an N1 FunctionSpec *draft* (NOT executable) with provenance,
source_hash, extraction_warnings, manual_review_required=True.

Hard rules (per protocol):
- Read-only: never mutates the source asset.
- Never guesses formula / variables / preconditions / postconditions.
- If a required field cannot be reliably extracted -> mark BLOCKED, do not fabricate.
- Symbolic markdown only; no weight-space / probabilistic semantics.
"""
import hashlib
import json
import os
import re
from typing import Dict, Any, Optional

ALLOWED_CLASSES = {"IMPORTABLE_NOW"}
SPEC_VERSION = "0.2.1-candidate"


def _source_hash(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _extract_title(text: str) -> Optional[str]:
    for line in text.splitlines():
        m = re.match(r"^#+\s+(.*)$", line.strip())
        if m:
            return m.group(1).strip()
    return None


def _count_symbols(text: str) -> int:
    math_blocks = len(re.findall(r"\$\$.*?\$\$|\$.*?\$", text, re.S))
    ops = len(re.findall(r"[∀∃∈⊆⊂→↔∧∨¬⇒⇔∂∇∫∑∏≡≈≤≥]", text))
    return math_blocks + ops


def import_asset(asset_record: Dict[str, Any], source_text: Optional[str] = None) -> Dict[str, Any]:
    if asset_record.get("classification") not in ALLOWED_CLASSES:
        return {
            "status": "BLOCKED",
            "reason": "asset not in IMPORTABLE_NOW set; importer is read-only and scoped",
            "asset_id": asset_record.get("asset_id"),
        }
    if source_text is None:
        return {
            "status": "BLOCKED",
            "reason": "source_text not supplied; importer refuses to guess asset body",
            "asset_id": asset_record.get("asset_id"),
            "manual_review_required": True,
        }
    src_hash = _source_hash(source_text)
    title = _extract_title(source_text)
    sym = _count_symbols(source_text)
    warnings = []
    if title is None:
        warnings.append("no markdown heading found; name unset")
    if sym == 0:
        warnings.append("no symbolic/math content detected; likely non-symbolic")
    draft = {
        "function_id": "DRAFT-" + asset_record["asset_id"],
        "spec_version": SPEC_VERSION,
        "name": title or asset_record["file_name"],
        "domain": "legacy_symbolic",
        "inputs": {},
        "outputs": {},
        "preconditions": [],
        "postconditions": [],
        "effects_declared": ["pure"],
        "provenance": {
            "source_asset_id": asset_record["asset_id"],
            "source_path": asset_record.get("source_path"),
            "source_hash": src_hash,
            "carrier_type": asset_record.get("carrier_type"),
            "extraction_warnings": warnings,
            "manual_review_required": True,
            "importer": "legacy_asset_importer@v0.2.1-candidate",
        },
        "created_at": "2026-07-15T12:00:00Z",
    }
    return {"status": "DRAFT_OK", "draft": draft, "asset_id": asset_record["asset_id"]}


if __name__ == "__main__":
    print("legacy_asset_importer: read-only draft generator; run via tests.")

"""N1 FunctionSpec Parser — validates and parses FunctionSpec JSON.

v0.2: adapted from v0.1 with standard imports, no exec/compile.
"""
import json, hashlib, re

FUNCTION_ID_RE = re.compile(r'^FN-\d{8}-\d{4}$')
SEMVER_RE = re.compile(r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$')

class FunctionSpecParseError(Exception):
    pass

class N1FunctionSpecParser:
    VERSION = "0.2.1-candidate"

    SUPPORTED_DOMAIN = "symbolic"

    def parse(self, spec_json: str) -> dict:
        """Parse JSON string into validated FunctionSpec dict."""
        try:
            spec = json.loads(spec_json)
        except json.JSONDecodeError as e:
            raise FunctionSpecParseError(f"Invalid JSON: {e}")

        self._validate(spec)
        spec['spec_hash'] = self._compute_hash(spec)
        return spec

    def _validate(self, spec: dict):
        required = ['function_id', 'spec_version', 'name', 'domain', 'inputs',
                    'outputs', 'preconditions', 'postconditions', 'effects_declared',
                    'created_at']
        for field in required:
            if field not in spec:
                raise FunctionSpecParseError(f"Missing required field: {field}")

        if not FUNCTION_ID_RE.match(spec['function_id']):
            raise FunctionSpecParseError(
                f"Invalid function_id '{spec['function_id']}' (expected FN-YYYYMMDD-NNNN)")

        if not SEMVER_RE.match(spec.get('spec_version', '')):
            raise FunctionSpecParseError(
                f"Invalid spec_version '{spec.get('spec_version')}' (expected MAJOR.MINOR.PATCH)")
        if spec.get('spec_version') == '0.0.0':
            raise FunctionSpecParseError(
                "spec_version '0.0.0' is not allowed (must denote a real version)")

        if spec['domain'] != self.SUPPORTED_DOMAIN:
            raise FunctionSpecParseError(
                f"Domain '{spec['domain']}' not supported in v0.2 (symbolic only)")

        if not isinstance(spec['inputs'], dict) or len(spec['inputs']) == 0:
            raise FunctionSpecParseError("inputs must be non-empty object")
        for k, v in spec['inputs'].items():
            if not isinstance(v, str):
                raise FunctionSpecParseError(f"input '{k}' type must be string")

        if not isinstance(spec['outputs'], dict) or len(spec['outputs']) == 0:
            raise FunctionSpecParseError("outputs must be non-empty object")
        for k, v in spec['outputs'].items():
            if not isinstance(v, str):
                raise FunctionSpecParseError(f"output '{k}' type must be string")

        for ptype, pname in [('preconditions', 'precondition'), ('postconditions', 'postcondition')]:
            conds = spec.get(ptype, [])
            if not isinstance(conds, list):
                raise FunctionSpecParseError(f"{ptype} must be an array")
            for i, cond in enumerate(conds):
                if not isinstance(cond, dict):
                    raise FunctionSpecParseError(f"{pname}[{i}] must be an object")
                expr = cond.get('expression', '')
                if not expr or not isinstance(expr, str):
                    raise FunctionSpecParseError(
                        f"{pname}[{i}].expression must be a non-empty string")

        effects = spec.get('effects_declared', [])
        if not isinstance(effects, list) or len(effects) == 0:
            raise FunctionSpecParseError("effects_declared must be non-empty array")

    def _compute_hash(self, spec: dict):
        raw = json.dumps({
            k: spec[k] for k in sorted(spec.keys())
            if k in ('function_id', 'spec_version', 'name', 'domain', 'inputs',
                     'outputs', 'preconditions', 'postconditions', 'effects_declared')
        }, sort_keys=True, ensure_ascii=False)
        return hashlib.sha256(raw.encode('utf-8')).hexdigest()

